const express = require('express');
const app = express();

// Instead of app.get() which only handles GET, be explicit:
// app.route('/users')
//   .get(getUsersHandler)      // Only GET
//   .post(createUserHandler)   // Only POST
//   .put(updateUserHandler)    // Only PUT
//   .delete(deleteUserHandler); // Only DELETE

// Or use method restriction middleware:
function allowMethods(...allowedMethods) {
  return (req, res, next) => {
    if (!allowedMethods.includes(req.method)) {
      return res.status(405).json({ 
        error: 'Method Not Allowed',
        message: `Method ${req.method} is not allowed for this endpoint`
      });
    }
    next();
  };
}

app.get('/users', allowMethods('GET'), (req, res) => {
  // This route only accepts GET
