/**
 * Secure Express.js Application Template
 * Implements security best practices addressing OWASP Top 10 concerns
 */

// Load environment variables (only in non-production environments)
if (process.env.NODE_ENV !== 'production' && process.env.NODE_ENV !== 'test') {
  require('dotenv').config();
}

// Core dependencies
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// ============ CONFIGURATION ============
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const TRUST_PROXY = process.env.TRUST_PROXY === 'true';

// ============ SECURITY MIDDLEWARE ============

// 1. Security Headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // Consider removing 'unsafe-inline' in production
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
    }
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  // Additional helmet configurations...
}));

// 2. Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.NODE_ENV === 'test' ? 0 : 100, // Disable in test env
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,  // Disable the `X-RateLimit-*` headers
  trustProxy: TRUST_PROXY, // Trust proxy headers if behind a load balancer
});

// Apply to all requests
app.use(apiLimiter);

// Stricter limit for auth endpoints (example)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // limit each IP to 5 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  trustProxy: TRUST_PROXY,
});

// 3. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
    : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true, // Allow cookies to be sent
  optionsSuccessStatus: 200,
  preflightContinue: false,
};

app.use(cors(corsOptions));

// 4. Body Parsing (with size limits to prevent DoS)
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Additional Security Middleware
app.use(xss()); // Sanitize user input to prevent XSS
app.use(hpp()); // Protect against HTTP Parameter Pollution attacks

// ============ ENVIRONMENT VARIABLE VALIDATION ============
function validateEnvironment() {
  const requiredVars = ['PORT', 'NODE_ENV'];
  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }

  // Validate PORT is a valid number
  const portNum = parseInt(process.env.PORT, 10);
  if (isNaN(portNum) || portNum < 1 || portNum > 65535) {
    throw new Error(`Invalid PORT value: ${process.env.PORT}`);
  }

  // Add more validations as needed for your specific services
  /*
  if (process.env.DATABASE_URL && !/^postgres:\/\//.test(process.env.DATABASE_URL)) {
    throw new Error('Invalid DATABASE_URL format');
  }
  */
}

// Validate environment on startup
try {
  validateEnvironment();
} catch (error) {
  console.error('FATAL: Environment validation failed:', error.message);
  process.exit(1);
}

// ============ REQUEST LOGGING (BE CAREFUL WITH SENSITIVE DATA) ============
app.use((req, res, next) => {
  // Log request metadata (avoid logging sensitive data)
  const logMeta = {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip || req.connection.remoteAddress,
    userAgent: req.get('User-Agent') || 'unknown'
  };

  // In production, you might want to use a proper logging library like Winston or Pino
  if (NODE_ENV !== 'test') {
    console.log(`[REQUEST]`, JSON.stringify(logMeta));
  }

