// Secure version of app.js with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors({     // Configure CORS properly
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  credentials: true
}));
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint (no auth needed)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Protected users endpoint (example with authentication middleware)
app.get('/users', authenticateToken, authorizeRole('admin'), getUsers);

// Example authentication middleware (simplified)
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // In real implementation, verify JWT token here
  // For demo, we'll just attach a fake user
  req.user = { id: 1, role: 'admin' };
  next();
}

// Example authorization middleware
function authorizeRole(role) {
  return (req, res, next) => {
    if (req.user && req.user.role === role) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
}

// Secure users endpoint handler
function getUsers(req, res) {
  // In real app, fetch from database with proper querying
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Only return necessary fields (data minimization)
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name
    // Email omitted for demo - would be included only if needed and user authorized
  }));

  res.json(sanitizedUsers);
}

// Global error handler (prevents leaking stack traces)
app.use((error, req, res, next) => {
  console.error(error); // Log error internally

  // Don't leak stack trace to client in production
  const statusCode = error.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : error.message;

  res.status(statusCode).json({ 
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

